// Source-specific looking exercises. Image credits and linked entries retain their provenance.
const b=(en,zh)=>({en,zh});
export const VISUAL_STUDIES=[
 {id:'remembering-three-kingdoms',assets:['china-rebuild-cao-cao','china-rebuild-zhuge-liang'],title:b('How later ages pictured the Three Kingdoms','后世如何描绘三国人物'),question:b('What do the framing, clothing and inscriptions ask you to notice about authority?','构图、衣冠与题字，如何引导你理解人物的权威？'),observations:[
 b('The Cao Cao image is a close, linear book illustration. Its heading calls him Wei Taizu, a royal posthumous title. The Sancai Tuhui was printed in 1609, long after his death in 220.','曹操图是近景线描书籍插图，题为“魏太祖像”，使用追尊庙号。《三才图会》于1609年刊行，距他220年去世已很久。'),
 b('The Ming painting presents Zhuge Liang standing in layered robes, with inscriptions and seals around him. Compare what each format can show. These images document later commemoration, not eyewitness likenesses of the third-century figures.','明代画中的诸葛亮身着层叠衣袍站立，周围可见题字和印章。比较两种载体各能表现什么：它们记录的是后世纪念方式，而非三世纪人物的现场肖像。')]},
 {id:'petition-and-treaty',assets:['atlantic-rebuild-cherokee','atlantic-rebuild-navajo'],title:b('Who could speak for a nation?','谁有权代表一个民族？'),question:b('Compare an argument against a treaty with the names and marks on another treaty. What does each page record?','把反对条约的陈情与另一份条约上的姓名、签押对读：两页各记录了什么？'),observations:[
 b('The 1836 Cherokee petition challenges the authority of the people who signed New Echota. Its written argument asks the US Senate not to ratify that agreement. This is a protest document, not the treaty itself.','1836年切罗基请愿书质疑新埃科塔条约签署者的代表资格，请求美国参议院不要批准协定。这是抗议文献，而非条约本身。'),
 b('The 1868 Navajo page records US commissioners and Navajo names with marks. Follow its story to the years of forced removal and confinement before return. Different nations, dates and political circumstances produced these two documents.','1868年纳瓦霍条约页列有美国专员及纳瓦霍代表的姓名和签押。沿相关故事可读到获准返回前的强制迁徙与拘禁。两份文献来自不同民族、年代及政治处境。')]},
 {id:'independence-and-government',assets:['atlantic-rebuild-declaration-of-independence','atlantic-rebuild-constitution'],title:b('Declaring independence, designing government','宣告独立，设计政府'),question:b('How does a declaration of political separation differ from a framework for governing?','政治分离的宣言与治理框架，有什么不同？'),observations:[
 b('The 1776 Declaration explains and announces separation from Britain. This is the faded engrossed parchment; its present appearance reflects its material history, not how clearly every copy could be read in 1776.','1776年《独立宣言》说明并宣告与英国分离。这是如今已褪色的誊清羊皮纸，其现状反映保存历程，并不表示1776年的所有版本都如此难辨。'),
 b('The 1787 Constitution sets out institutions and powers. Open the linked entries to compare the eleven-year gap, the Articles of Confederation between them, and the people excluded from the political equality these documents invoked.','1787年《宪法》规定机构及权力。打开关联条目，比较其间十一年的变化、《邦联条例》的过渡安排，以及被这些文献所诉诸的政治平等排除的人群。')]}];
export function availableVisualStudies(rows){const ids=new Set(rows.map(r=>r.id));return VISUAL_STUDIES.filter(s=>s.assets.length===2&&new Set(s.assets).size===2&&s.assets.every(id=>ids.has(id)));}
export function matchingVisualStudy(ids){if(ids.length!==2||new Set(ids).size!==2)return null;return VISUAL_STUDIES.find(s=>s.assets.every(id=>ids.includes(id)))||null;}
